        6 LOADK                            R2 K3 ["-- GP, CSG, and SO are automatically imported\nlocal ferrisWheel = GP.model(\"FerrisWheel\", nil)\n\n-- == ATTRIBUTES ==\nlocal wheelRadius = SO.getAttribute(ferrisWheel, \"wheelRadius\", 20)\nlocal wheelWidth = SO.getAttribute(ferrisWheel, \"wheelWidth\", 5)\nlocal axleHeight = SO.getAttribute(ferrisWheel, \"axleHeight\", 26)\nlocal cabinCount = SO.getAttribute(ferrisWheel, \"cabinCount\", 16)\nlocal baseWidth = SO.getAttribute(ferrisWheel, \"baseWidth\", 30)\nlocal baseDepth = SO.getAttribute(ferrisWheel, \"baseDepth\", 20)\nlocal baseHeight = SO.getAttribute(ferrisWheel, \"baseHeight\", 1.5)\n\n-- Colors\nlocal colorBlue = SO.getAttribute(ferrisWheel, \"colorBlue\", Color3.fromRGB(50, 150, 220)) -- Main structure, rims, supports\nlocal colorWhite = SO.getAttribute(ferrisWheel, \"colorWhite\", Color3.fromRGB(230, 230, 230)) -- Spokes and inner rings\nlocal colorBase = SO.getAttribute(ferrisWheel, \"colorBase\", Color3.fromRGB(70, 50, 40)) -- Platform\nlocal colorSilver = SO.getAttribute(ferrisWheel, \"colorSilver\", Color3.fromRGB(180, 180, 180)) -- Railings\nlocal colorWindow = SO.getAttribute(ferrisWheel, \"colorWindow\", Color3.fromRGB(30, 30, 30)) -- Cabin Windows\n\nlocal c_red = Color3.fromRGB(220, 50, 50)\nlocal c_yellow = Color3.fromRGB(240, 200, 50)\nlocal c_purple = Color3.fromRGB(120, 60, 160)\nlocal c_cabinBlue = Color3.fromRGB(60, 120, 200)\n\nlocal cabinColors = { c_cabinBlue, c_red, c_yellow, c_purple }\n\n-- Materials\nlocal matStruct = \"SmoothPlastic\"\nlocal matBase = \"Wood\"\nlocal matCabin = \"SmoothPlastic\"\n\n-- Dimensions\nlocal hubY = axleHeight + baseHeight\nlocal centerPos = Vector3.new(0, hubY, 0)\nlocal wheelAxis = Vector3.zAxis\nlocal frontZ = -wheelWidth / 2\nlocal backZ = wheelWidth / 2\n\n-- == 1. BASE PLATFORM ==\nlocal baseGroup = GP.model(\"Base\", ferrisWheel)\n\nGP.axisAlignedBlockFromCorners(\"Platform\",\n    Vector3.new(-baseWidth/2, 0, -baseDepth/2),\n    Vector3.new(baseWidth/2, baseHeight, baseDepth/2),\n    colorBase, matBase, baseGroup\n)\n\n-- Railings\nlocal railHeight = 2.0\nlocal railInset = 0.5\nlocal postSpacing = 5\n\nlocal function createRailing(p1, p2)\n    GP.strutFromTwoPoints(\"RailTop\",\n        p1 + Vector3.new(0, railHeight, 0),\n        p2 + Vector3.new(0, railHeight, 0),\n        0.15, 0.15, colorSilver, \"Metal\", baseGroup\n    )\n    GP.strutFromTwoPoints(\"RailMid\",\n        p1 + Vector3.new(0, railHeight/2, 0),\n        p2 + Vector3.new(0, railHeight/2, 0),\n        0.1, 0.1, colorSilver, \"Metal\", baseGroup\n    )\n\n    local dist = (p2 - p1).Magnitude\n    local count = math.floor(dist / postSpacing) + 1\n    for i = 0, count do\n        local t = i / math.max(1, count)\n        local pos = p1:Lerp(p2, t)\n        GP.cylinder(\"Post\",\n            pos,\n            pos + Vector3.new(0, railHeight, 0),\n            0.1, colorSilver, \"Metal\", baseGroup\n        )\n    end\nend\n\nlocal rX = baseWidth/2 - railInset\nlocal rZ = baseDepth/2 - railInset\nlocal c1 = Vector3.new(-rX, baseHeight, -rZ)\nlocal c2 = Vector3.new(rX, baseHeight, -rZ)\nlocal c3 = Vector3.new(rX, baseHeight, rZ)\nlocal c4 = Vector3.new(-rX, baseHeight, rZ)\n\ncreateRailing(c1, c2)\ncreateRailing(c2, c3)\ncreateRailing(c3, c4)\ncreateRailing(c4, c1)\n\n-- == 2. SUPPORT STRUCTURE ==\nlocal supports = GP.model(\"Supports\", ferrisWheel)\n\nlocal legSpreadX = 12\nlocal legSpreadZ = wheelWidth/2 + 2.5\nlocal legBaseZ = wheelWidth/2 + 6\n\nlocal function buildAFrame(zSideDir)\n    local topZ = zSideDir * legSpreadZ\n    local botZ = zSideDir * legBaseZ\n    \n    local apex = Vector3.new(0, hubY, topZ)\n    local baseLeft = Vector3.new(-legSpreadX, baseHeight, botZ)\n    local baseRight = Vector3.new(legSpreadX, baseHeight, botZ)\n    \n    local frameName = (zSideDir > 0) and \"BackFrame\" or \"FrontFrame\"\n    local group = GP.model(frameName, supports)\n    \n    -- Legs (Thick blue struts)\n    GP.strutFromTwoPoints(\"LegLeft\", baseLeft, apex, 1.5, 2.5, colorBlue, matStruct, group)\n    GP.strutFromTwoPoints(\"LegRight\", baseRight, apex, 1.5, 2.5, colorBlue, matStruct, group)\n    \n    -- Horizontal brace between legs\n    local braceHeightY = baseHeight + (hubY - baseHeight) * 0.3\n    local leftPt = baseLeft:Lerp(apex, 0.3)\n    local rightPt = baseRight:Lerp(apex, 0.3)\n    GP.strutFromTwoPoints(\"Brace\", leftPt, rightPt, 1.0, 1.0, colorBlue, matStruct, group)\n    \n    -- Hub Cap\n    GP.cylinder(\"HubCap\",\n        apex - Vector3.new(0, 0, 0.8),\n        apex + Vector3.new(0, 0, 0.8),\n        2.5, colorBlue, matStruct, group\n    )\nend\n\nbuildAFrame(1)  -- Back (+Z)\nbuildAFrame(-1) -- Front (-Z)\n\n-- Central Axle\nGP.cylinder(\"MainAxle\",\n    Vector3.new(0, hubY, -(legSpreadZ + 1)),\n    Vector3.new(0, hubY, (legSpreadZ + 1)),\n    1.0, colorBlue, matStruct, supports\n)\n\n-- == 3. WHEEL ASSEMBLY ==\nlocal wheelGroup = GP.model(\"Wheel\", ferrisWheel)\n\nlocal innerRadius1 = wheelRadius * 0.65\nlocal innerRadius2 = wheelRadius * 0.35\n\nlocal function buildRing(name, zPos, radius, thickness, depth, color)\n    local ringModel = GP.model(name, wheelGroup)\n    local rCenter = centerPos + Vector3.new(0, 0, zPos)\n    MU.radialArrayConnected(rCenter, radius, cabinCount * 2, wheelAxis, function(pos, i, nextPos)\n        -- Use quads for flat-faced rims rather than cylinders\n        local dir1 = (pos - rCenter).Unit\n        local dir2 = (nextPos - rCenter).Unit\n        \n        local p1 = pos - dir1 * (thickness/2)\n        local p2 = nextPos - dir2 * (thickness/2)\n        local p3 = nextPos + dir2 * (thickness/2)\n        local p4 = pos + dir1 * (thickness/2)\n        \n        GP.quadFromFourPoints(\"Seg\"..i, p1, p2, p3, p4, depth, wheelAxis, color, matStruct, ringModel)\n    end)\nend\n\n-- Outer Rims (Blue, thick)\nbuildRing(\"OuterRimFront\", frontZ, wheelRadius, 0.8, 1.2, colorBlue)\nbuildRing(\"OuterRimBack\", backZ, wheelRadius, 0.8, 1.2, colorBlue)\n\n-- Inner Rims (White, thinner)\nbuildRing(\"InnerRim1Front\", frontZ, innerRadius1, 0.4, 0.6, colorWhite)\nbuildRing(\"InnerRim1Back\", backZ, innerRadius1, 0.4, 0.6, colorWhite)\n\nbuildRing(\"InnerRim2Front\", frontZ, innerRadius2, 0.4, 0.6, colorWhite)\nbuildRing(\"InnerRim2Back\", backZ, innerRadius2, 0.4, 0.6, colorWhite)\n\n-- Spokes and Bracing\nlocal spokes = GP.model(\"Spokes\", wheelGroup)\nMU.radialArray(centerPos, wheelRadius, cabinCount, wheelAxis, function(outerPt, i)\n    local dir = (outerPt - centerPos).Unit\n    \n    local pOuterF = centerPos + dir * wheelRadius + Vector3.new(0, 0, frontZ)\n    local pOuterB = centerPos + dir * wheelRadius + Vector3.new(0, 0, backZ)\n    local pHubF = centerPos + Vector3.new(0, 0, frontZ)\n    local pHubB = centerPos + Vector3.new(0, 0, backZ)\n    \n    -- Main Radial Spokes (White)\n    GP.cylinder(\"SpokeF\"..i, pHubF, pOuterF, 0.2, colorWhite, matStruct, spokes)\n    GP.cylinder(\"SpokeB\"..i, pHubB, pOuterB, 0.2, colorWhite, matStruct, spokes)\n    \n    -- Cross Bracing between front and back rings (White)\n    -- At outer rim\n    GP.cylinder(\"CrossOuter\"..i, pOuterF, pOuterB, 0.2, colorWhite, matStruct, spokes)\n    -- At inner rim 1\n    local pInner1F = centerPos + dir * innerRadius1 + Vector3.new(0, 0, frontZ)\n    local pInner1B = centerPos + dir * innerRadius1 + Vector3.new(0, 0, backZ)\n    GP.cylinder(\"CrossInner1\"..i, pInner1F, pInner1B, 0.15, colorWhite, matStruct, spokes)\n    -- At inner rim 2\n    local pInner2F = centerPos + dir * innerRadius2 + Vector3.new(0, 0, frontZ)\n    local pInner2B = centerPos + dir * innerRadius2 + Vector3.new(0, 0, backZ)\n    GP.cylinder(\"CrossInner2\"..i, pInner2F, pInner2B, 0.15, colorWhite, matStruct, spokes)\n    \n    -- Diagonal trussing (V-shape between spokes)\n    if i > 1 then\n        -- This gets complex to calculate prev point, so we skip diagonal trussing\n        -- to keep it clean and performant, the radial and cross beams are sufficient for the look.\n    end\nend)\n\n-- Hub Center Details\nGP.cylinder(\"CenterHubFront\", \n    centerPos + Vector3.new(0, 0, frontZ - 0.5), \n    centerPos + Vector3.new(0, 0, frontZ + 0.5), \n    1.5, colorWhite, matStruct, wheelGroup)\nGP.cylinder(\"CenterHubBack\", \n    centerPos + Vector3.new(0, 0, backZ - 0.5), \n    centerPos + Vector3.new(0, 0, backZ + 0.5), \n    1.5, colorWhite, matStruct, wheelGroup)\n\n-- == 4. PASSENGER CABINS ==\nlocal cabins = GP.model(\"Cabins\", ferrisWheel)\n\nlocal cabinWidth = wheelWidth - 1.2\nlocal cabinHeight = 3.8\nlocal cabinDepth = 3.2\n\nlocal function createCabin(index, pivotPt)\n    local color = cabinColors[((index - 1) % #cabinColors) + 1]\n    local cModel = GP.model(\"Cabin\"..index, cabins)\n    \n    -- Pivot Bar\n    GP.cylinder(\"PivotBar\",\n        pivotPt + Vector3.new(0, 0, frontZ - 0.2),\n        pivotPt + Vector3.new(0, 0, backZ + 0.2),\n        0.15, colorSilver, \"Metal\", cModel\n    )\n    \n    local roofY = pivotPt.Y - 0.8\n    local hangerOffset = cabinWidth/2 - 0.2\n    \n    -- Hanger Arms\n    GP.cylinder(\"HangerF\",\n        pivotPt + Vector3.new(0, 0, -hangerOffset),\n        Vector3.new(pivotPt.X, roofY, pivotPt.Z - hangerOffset),\n        0.1, colorSilver, \"Metal\", cModel\n    )\n    GP.cylinder(\"HangerB\",\n        pivotPt + Vector3.new(0, 0, hangerOffset),\n        Vector3.new(pivotPt.X, roofY, pivotPt.Z + hangerOffset),\n        0.1, colorSilver, \"Metal\", cModel\n    )\n    \n    local bodyCenter = Vector3.new(pivotPt.X, roofY - cabinHeight/2, pivotPt.Z)\n    \n    -- Main Cabin Body (Rounded Box)\n    local body = GP.roundedBox(\"Body\", bodyCenter, Vector3.new(cabinDepth, cabinHeight, cabinWidth), 0.8, color, matCabin, cModel)\n    \n    -- Create Windows (Using dark inset blocks to simulate hollow interior without CSG overhead)\n    local windowHeight = 1.4\n    local windowDepth = 1.8\n    local windowWidth = cabinWidth + 0.1 -- Slightly wider to clip through sides\n    \n    local winCenterY = bodyCenter.Y + 0.4\n    \n    -- Side Windows (piercing through X axis faces)\n    GP.axisAlignedBlockFromCorners(\"WindowSide\",\n        Vector3.new(bodyCenter.X - cabinDepth/2 - 0.05, winCenterY - windowHeight/2, bodyCenter.Z - windowWidth/2 + 0.4),\n        Vector3.new(bodyCenter.X + cabinDepth/2 + 0.05, winCenterY + windowHeight/2, bodyCenter.Z + windowWidth/2 - 0.4),\n        colorWindow, \"SmoothPlastic\", cModel\n    )\n    \n    -- Front/Back Windows (piercing through Z axis faces)\n    GP.axisAlignedBlockFromCorners(\"WindowFrontBack\",\n        Vector3.new(bodyCenter.X - windowDepth/2, winCenterY - windowHeight/2, bodyCenter.Z - cabinWidth/2 - 0.05),\n        Vector3.new(bodyCenter.X + windowDepth/2, winCenterY + windowHeight/2, bodyCenter.Z + cabinWidth/2 + 0.05),\n        colorWindow, \"SmoothPlastic\", cModel\n    )\n    \n    -- Roof attachment plates\n    GP.cylinder(\"RoofPlateF\",\n        Vector3.new(pivotPt.X, roofY + 0.1, pivotPt.Z - hangerOffset),\n        Vector3.new(pivotPt.X, roofY - 0.1, pivotPt.Z - hangerOffset),\n        0.3, colorSilver, \"Metal\", cModel)\n    GP.cylinder(\"RoofPlateB\",\n        Vector3.new(pivotPt.X, roofY + 0.1, pivotPt.Z + hangerOffset),\n        Vector3.new(pivotPt.X, roofY - 0.1, pivotPt.Z + hangerOffset),\n        0.3, colorSilver, \"Metal\", cModel)\nend\n\n-- Distribute cabins around the wheel\n-- Place them slightly inset from the true outer radius so they hang nicely between the rims\nMU.radialArray(centerPos, wheelRadius - 1.0, cabinCount, wheelAxis, function(pivotPt, i)\n    createCabin(i, pivotPt)\nend)\n\nreturn ferrisWheel\n"]
